function(){
    var productName = {{[VAR] DataLayer - Product Name}};
    var description = {{[VAR] DataLayer - Description}};

    if(productName.indexOf("Combo") != -1) { return productName; }
    if({{[VAR] DataLayer - Checkout Type}} == "plano-profissional" && productName.indexOf("Plano") == -1) { return description; }

    if (productName === "-" || productName === "" || productName === null || typeof productName === "undefined") {
        return description;
    } else {

        if({{[VAR] DataLayer - Checkout Type}} == "payg") { return description;}
        return productName;
    }
}

