}

function defineLeadPage() {
  var url = document.location.href;
  var lead_category;

  if (url.indexOf("planos-veiculos-autonomo") != -1) {
    lead_category = "veiculos-autonomo";
  }
  else if (url.indexOf("planos-veiculos-empresa") != -1) {
    lead_category = "veiculos-empresa";
  } 
  else if (url.indexOf("motorcycles-subscription") != -1 || url.indexOf("planos-motos") != -1) {
    lead_category = "motos";
  }
  else if (url.indexOf("trucks-subscription") != -1 || url.indexOf("planos-caminhoes") != -1) {
    lead_category = "caminhões";
  } 
  else if (url.indexOf("boats-subscription") != -1 || url.indexOf("planos-barcos") != -1) {
    lead_category = "barcos";
  }

  return lead_category;
}

